from html.parser import HTMLParser
class P(HTMLParser):
 def __init__(self): super().__init__();self.skip=0;self.a=False
 def handle_starttag(self,t,a):
  if t in ['script','style']:self.skip+=1
  if t=='article':self.a=True
  if self.a and t=='a':print('LINK',dict(a).get('href'))
 def handle_endtag(self,t):
  if t in ['script','style']:self.skip-=1
  if t=='article':self.a=False
 def handle_data(self,d):
  if self.a and not self.skip and d.strip():print(d.strip())
p=P();p.feed(open('products/services/new-actionable-buyers/canadian-project.html').read())
